def solve(g, marker):
    H=len(g); W=len(g[0])
    co=[(r,c) for r in range(H) for c in range(W) if g[r][c]==marker]
    a=min(x for x,y in co); b=max(x for x,y in co); d=min(y for x,y in co); e=max(y for x,y in co)
    o=[row[:] for row in g]
    for r in range(H):
        for c in range(W):
            if ((r in (a,b) and d<=c<=e) or (c in (d,e) and a<=r<=b)):
                corner = (r in (a,b) and c in (d,e))
                if g[r][c]!=marker or not corner:
                    o[r][c]=2
    return o
