def solve2(g, marker, maxd=7):
    H,W=len(g),len(g[0])
    o=[row[:] for row in g]
    for r in range(H):
        pos=[c for c in range(W) if g[r][c]==marker]
        for a,b in zip(pos,pos[1:]):
            if b-a-1<=maxd-1:
                for c in range(a+1,b): o[r][c]=2
    for c in range(W):
        pos=[r for r in range(H) if g[r][c]==marker]
        for a,b in zip(pos,pos[1:]):
            if b-a-1<=maxd-1:
                for r in range(a+1,b): o[r][c]=2
    return o
def check(g,marker,exp):
