def solve3(g, marker, maxd=7):
    H,W=len(g),len(g[0])
    co=[(r,c) for r in range(H) for c in range(W) if g[r][c]==marker]
    a=min(x for x,y in co); b=max(x for x,y in co); d=min(y for x,y in co); e=max(y for x,y in co)
    o=[row[:] for row in g]
    for r in range(H):
        for c in range(W):
            if g[r][c]==marker: continue
            fill = ((r in (a,b) and d<=c<=e) or (c in (d,e) and a<=r<=b))
            if not fill:
                rowm=[x for x in range(W) if g[r][x]==marker]
                for p,q in zip(rowm,rowm[1:]):
                    if p<c<q and q-p-1<=maxd-1: fill=True
                if not fill:
                    colm=[x for x in range(H) if g[x][c]==marker]
                    for p,q in zip(colm,colm[1:]):
                        if p<r<q and q-p-1<=maxd-1: fill=True
            if fill: o[r][c]=2
    return o
